}

pub fn parse_and_dispatch(bin_name: &str, args: &[String]) -> Result<u8, CliError> {
    // Top-level options: --help/-h, --version/-V.
    // If the first argument is a top-level flag, handle it.
    // Otherwise, interpret as subcommand.
    let mut i = 0;
    while i < args.len() {
        let a = &args[i];
        if a == "--help" || a == "-h" {
            print!("{}", help_text::render(help_text::MAIN, bin_name));
            return Ok(0);
        }
        if a == "--version" || a == "-V" {
            println!("tree-sitter 0.27.0");
            return Ok(0);
        }
        if a.starts_with('-') && a != "-" {
            return Err(CliError::UnexpectedArgument {
                arg: a.clone(),
                cmd: None,
                tip: false,
            });
        }
        // Subcommand
        let sub = a.clone();
        let spec = match commands::find(&sub) {
            Some(c) => c,
            None => {
                return Err(CliError::UnrecognizedSubcommand { name: sub });
            }
        };
        let rest = &args[i + 1..];
        let parsed = parse_command(spec, rest, bin_name)?;
        return commands::run(spec, parsed, bin_name);
    }
    // No args given: print main help and exit 2.
    print!("{}", help_text::render(help_text::MAIN, bin_name));
    Ok(2)
}

fn find_option<'a>(spec: &'a CommandSpec, name: &str, is_long: bool) -> Option<&'a OptionSpec> {
    for o in spec.options {
        if is_long {
            if o.long == name {
                return Some(o);
            }
        } else if let Some(s) = o.short {
            if name.len() == 1 && name.chars().next().unwrap() == s {
                return Some(o);
            }
        }
    }
    None
}

fn validate_value(
    opt: &OptionSpec,
    value: &str,
) -> Result<(), CliError> {
    if let Some(pvs) = opt.possible_values {
        if !pvs.iter().any(|p| *p == value) {
            return Err(CliError::InvalidValue {
                value: value.to_string(),
                display: opt.display,
                possible_values: Some(pvs),
            });
        }
    }
    Ok(())
}

