use std::collections::HashMap;
use std::path::Path;

use crate::commands;
use crate::help_text;

pub fn bin_name_from_argv0(argv0: &str) -> String {
    let p = Path::new(argv0);
    p.file_name()
        .map(|s| s.to_string_lossy().into_owned())
        .unwrap_or_else(|| "tree-sitter".to_string())
}

#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub enum Arity {
    /// Flag with no value.
    Flag,
    /// Option with one required value.
    Value,
    /// Option that may take an optional value (like `-d [<DEBUG>]`).
    Optional,
    /// Option that accepts multiple values (like `--edits <EDITS>...`).
    Multi,
}

#[derive(Debug, Clone)]
pub struct OptionSpec {
    pub long: &'static str,
    pub short: Option<char>,
    pub display: &'static str, // e.g. "--edits <EDITS>..."
    pub arity: Arity,
    pub possible_values: Option<&'static [&'static str]>,
}

#[derive(Debug, Clone)]
pub struct CommandSpec {
    pub name: &'static str,
    pub usage_line: &'static str,      // e.g. "{BIN} parse [OPTIONS] [PATHS]..."
    pub help_long: &'static str,
    pub help_short: Option<&'static str>,
    pub options: &'static [OptionSpec],
    /// True if the command accepts any number of positional arguments,
    /// or has a positional "value" argument that could be mistaken for an option.
    pub tip_on_unknown_option: bool,
    /// Accept free positional arguments.
    pub accepts_positional: bool,
    /// Has at least one *required* positional argument (like `query`'s QUERY_PATH).
    pub required_positional: Option<&'static str>,
    /// Max number of positional args if limited (None = unlimited).
    pub max_positional: Option<usize>,
}

pub struct ParsedArgs {
    pub flags: HashMap<&'static str, bool>,
    pub values: HashMap<&'static str, Vec<String>>,
    pub positional: Vec<String>,
}

impl ParsedArgs {
    pub fn new() -> Self {
        Self {
            flags: HashMap::new(),
            values: HashMap::new(),
            positional: Vec::new(),
        }
    }
    pub fn has(&self, long: &str) -> bool {
        self.flags.get(long).copied().unwrap_or(false)
            || self.values.contains_key(long)
    }
    pub fn first(&self, long: &str) -> Option<&String> {
        self.values.get(long).and_then(|v| v.first())
    }
}

#[derive(Debug)]
pub enum CliError {
    UnrecognizedSubcommand {
        name: String,
    },
    UnexpectedArgument {
        arg: String,
        cmd: Option<&'static CommandSpec>,
        tip: bool,
    },
    MissingValue {
        display: &'static str,
        possible_values: Option<&'static [&'static str]>,
    },
    InvalidValue {
        value: String,
        display: &'static str,
        possible_values: Option<&'static [&'static str]>,
    },
    MissingRequired {
        names: Vec<String>,
        usage: String,
    },
    DuplicateArgument {
        display: &'static str,
        usage: String,
    },
    EqualsForFlag {
        flag: String,
    },
}

impl CliError {
    pub fn exit_code(&self) -> u8 {
        2
    }
    pub fn emit(&self, bin_name: &str) {
        match self {
            CliError::UnrecognizedSubcommand { name } => {
                eprintln!("error: unrecognized subcommand '{}'", name);
                eprintln!();
                eprintln!("Usage: {} <COMMAND>", bin_name);
                eprintln!();
                eprintln!("For more information, try '--help'.");
            }
            CliError::UnexpectedArgument { arg, cmd, tip } => {
                eprintln!("error: unexpected argument '{}' found", arg);
                if *tip {
                    eprintln!();
                    eprintln!("  tip: to pass '{}' as a value, use '-- {}'", arg, arg);
                }
                eprintln!();
                let usage = match cmd {
                    Some(c) => help_text::render(c.usage_line, bin_name),
                    None => format!("{} <COMMAND>", bin_name),
                };
                eprintln!("Usage: {}", usage);
                eprintln!();
                eprintln!("For more information, try '--help'.");
            }
            CliError::MissingValue { display, possible_values } => {
                eprintln!(
                    "error: a value is required for '{}' but none was supplied",
                    display
                );
                if let Some(pv) = possible_values {
                    eprintln!("  [possible values: {}]", pv.join(", "));
                }
                eprintln!();
                eprintln!("For more information, try '--help'.");
            }
            CliError::InvalidValue {
                value,
                display,
                possible_values,
            } => {
                eprintln!("error: invalid value '{}' for '{}'", value, display);
                if let Some(pv) = possible_values {
                    eprintln!("  [possible values: {}]", pv.join(", "));
                }
                eprintln!();
                eprintln!("For more information, try '--help'.");
            }
            CliError::MissingRequired { names, usage } => {
                eprintln!("error: the following required arguments were not provided:");
                for n in names {
                    eprintln!("  {}", n);
                }
                eprintln!();
                eprintln!("Usage: {}", help_text::render(usage, bin_name));
                eprintln!();
                eprintln!("For more information, try '--help'.");
            }
            CliError::DuplicateArgument { display, usage } => {
                eprintln!(
                    "error: the argument '{}' cannot be used multiple times",
                    display
                );
                eprintln!();
                eprintln!("Usage: {}", help_text::render(usage, bin_name));
                eprintln!();
                eprintln!("For more information, try '--help'.");
            }
            CliError::EqualsForFlag { flag } => {
                eprintln!(
                    "error: unexpected value for '--{flag}' found; no more were expected"
                );
                eprintln!();
                eprintln!("For more information, try '--help'.");
            }
        }
    }
}

pub fn parse_and_dispatch(bin_name: &str, args: &[String]) -> Result<u8, CliError> {
    // Top-level options: --help/-h, --version/-V.
    // If the first argument is a top-level flag, handle it.
    // Otherwise, interpret as subcommand.
    let mut i = 0;
    while i < args.len() {
        let a = &args[i];
        if a == "--help" || a == "-h" {
            print!("{}", help_text::render(help_text::MAIN, bin_name));
            return Ok(0);
        }
        if a == "--version" || a == "-V" {
            println!("tree-sitter 0.27.0");
            return Ok(0);
        }
        if a.starts_with('-') && a != "-" {
            return Err(CliError::UnexpectedArgument {
                arg: a.clone(),
                cmd: None,
                tip: false,
            });
        }
        // Subcommand
        let sub = a.clone();
        let spec = match commands::find(&sub) {
            Some(c) => c,
            None => {
                return Err(CliError::UnrecognizedSubcommand { name: sub });
            }
        };
        let rest = &args[i + 1..];
        let parsed = parse_command(spec, rest, bin_name)?;
        return commands::run(spec, parsed, bin_name);
    }
    // No args given: print main help and exit 2.
    print!("{}", help_text::render(help_text::MAIN, bin_name));
    Ok(2)
}

fn find_option<'a>(spec: &'a CommandSpec, name: &str, is_long: bool) -> Option<&'a OptionSpec> {
    for o in spec.options {
        if is_long {
            if o.long == name {
                return Some(o);
            }
        } else if let Some(s) = o.short {
            if name.len() == 1 && name.chars().next().unwrap() == s {
                return Some(o);
            }
        }
    }
    None
}

fn validate_value(
    opt: &OptionSpec,
    value: &str,
) -> Result<(), CliError> {
    if let Some(pvs) = opt.possible_values {
        if !pvs.iter().any(|p| *p == value) {
            return Err(CliError::InvalidValue {
                value: value.to_string(),
                display: opt.display,
                possible_values: Some(pvs),
            });
        }
    }
    Ok(())
}

pub fn parse_command(
    spec: &'static CommandSpec,
    args: &[String],
    bin_name: &str,
) -> Result<ParsedArgs, CliError> {
    let _ = bin_name;
    let mut parsed = ParsedArgs::new();
    // Check for help flag anywhere first but without consuming it; however
    // clap consumes help as it's encountered.
    let mut i = 0;
    let mut saw_separator = false;
    while i < args.len() {
        let arg = &args[i];
        if !saw_separator && arg == "--" {
            saw_separator = true;
            i += 1;
            continue;
        }
        if !saw_separator && (arg == "--help" || arg == "-h") {
            let txt = if arg == "-h" {
                spec.help_short.unwrap_or(spec.help_long)
            } else {
                spec.help_long
            };
            print!("{}", help_text::render(txt, bin_name));
            std::process::exit(0);
        }
        if !saw_separator && arg.starts_with("--") && arg.len() > 2 {
            // Long option. Could be --name or --name=value.
            let body = &arg[2..];
            let (name, value_after_eq) = match body.find('=') {
                Some(p) => (&body[..p], Some(&body[p + 1..])),
                None => (body, None),
            };
            let opt = match find_option(spec, name, true) {
                Some(o) => o,
                None => {
                    return Err(CliError::UnexpectedArgument {
                        arg: arg.clone(),
                        cmd: Some(spec),
                        tip: spec.tip_on_unknown_option,
                    });
                }
            };
            match opt.arity {
                Arity::Flag => {
                    if value_after_eq.is_some() {
                        return Err(CliError::EqualsForFlag {
                            flag: name.to_string(),
                        });
                    }
                    if parsed.flags.insert(opt.long, true).is_some() {
                        // allow duplicates for plain flags? For now, ignore.
                    }
                }
                Arity::Value => {
                    let value = match value_after_eq {
                        Some(v) => v.to_string(),
                        None => match args.get(i + 1) {
                            Some(v) => {
                                i += 1;
                                v.clone()
                            }
                            None => {
                                return Err(CliError::MissingValue {
                                    display: opt.display,
                                    possible_values: opt.possible_values,
                                });
                            }
                        },
                    };
                    if value_after_eq.is_none() && value.starts_with('-') && value != "-" {
                        return Err(CliError::MissingValue {
                            display: opt.display,
                            possible_values: opt.possible_values,
                        });
                    }
                    validate_value(opt, &value)?;
                    if parsed.values.contains_key(opt.long) {
                        return Err(CliError::DuplicateArgument {
                            display: opt.display,
                            usage: spec.usage_line.to_string(),
                        });
                    }
                    parsed.values.insert(opt.long, vec![value]);
                }
                Arity::Optional => {
                    let value = match value_after_eq {
                        Some(v) => v.to_string(),
                        None => String::new(),
                    };
                    if !value.is_empty() {
                        validate_value(opt, &value)?;
                    }
                    let v = parsed.values.entry(opt.long).or_insert_with(Vec::new);
                    v.push(value);
                }
                Arity::Multi => {
                    let first = match value_after_eq {
                        Some(v) => v.to_string(),
                        None => match args.get(i + 1) {
                            Some(v) => {
                                i += 1;
                                v.clone()
                            }
                            None => {
                                return Err(CliError::MissingValue {
                                    display: opt.display,
                                    possible_values: opt.possible_values,
                                });
                            }
                        },
                    };
                    validate_value(opt, &first)?;
                    parsed
                        .values
                        .entry(opt.long)
                        .or_insert_with(Vec::new)
                        .push(first);
                    // In clap, `Multi` with `num_args = 1..` consumes additional
                    // values from subsequent positional args until a flag is hit.
                    // We mimic a simpler behavior: only one value per occurrence
                    // unless more follow directly as non-flags.
                    if value_after_eq.is_none() {
                        while let Some(next) = args.get(i + 1) {
                            if next.starts_with('-') && next != "-" {
                                break;
                            }
                            i += 1;
                            parsed
                                .values
                                .get_mut(opt.long)
                                .unwrap()
                                .push(next.clone());
                        }
                    }
                }
            }
            i += 1;
            continue;
        }
        if !saw_separator && arg.starts_with('-') && arg.len() > 1 && arg != "-" {
            // Short option. Could be -s, -sVALUE, -s VALUE, -s=VALUE, or combined -abc.
            let body = &arg[1..];
            let first_ch = body.chars().next().unwrap();
            let opt = match find_option(spec, &first_ch.to_string(), false) {
                Some(o) => o,
                None => {
                    return Err(CliError::UnexpectedArgument {
                        arg: arg.clone(),
                        cmd: Some(spec),
                        tip: spec.tip_on_unknown_option,
                    });
                }
            };
            let tail = &body[first_ch.len_utf8()..];
            match opt.arity {
                Arity::Flag => {
                    parsed.flags.insert(opt.long, true);
                    // If there is more after, treat each as another short flag.
                    let mut rest = tail;
                    while !rest.is_empty() {
                        let c = rest.chars().next().unwrap();
                        if let Some(o2) = find_option(spec, &c.to_string(), false) {
                            match o2.arity {
                                Arity::Flag => {
                                    parsed.flags.insert(o2.long, true);
                                    rest = &rest[c.len_utf8()..];
                                }
                                _ => {
                                    // Remaining is value for this non-flag option.
                                    let value = rest[c.len_utf8()..].to_string();
                                    let value = if value.starts_with('=') {
                                        value[1..].to_string()
                                    } else {
                                        value
                                    };
                                    if value.is_empty() {
                                        match o2.arity {
                                            Arity::Optional => {
                                                parsed
                                                    .values
                                                    .entry(o2.long)
                                                    .or_insert_with(Vec::new)
                                                    .push(String::new());
                                            }
                                            _ => {
                                                let v = match args.get(i + 1) {
                                                    Some(v) => {
                                                        i += 1;
                                                        v.clone()
                                                    }
                                                    None => {
                                                        return Err(CliError::MissingValue {
                                                            display: o2.display,
                                                            possible_values: o2.possible_values,
                                                        });
                                                    }
                                                };
                                                validate_value(o2, &v)?;
                                                parsed
                                                    .values
                                                    .entry(o2.long)
                                                    .or_insert_with(Vec::new)
                                                    .push(v);
                                            }
                                        }
                                    } else {
                                        validate_value(o2, &value)?;
                                        parsed
                                            .values
                                            .entry(o2.long)
                                            .or_insert_with(Vec::new)
                                            .push(value);
                                    }
                                    break;
                                }
                            }
                        } else {
                            return Err(CliError::UnexpectedArgument {
                                arg: format!("-{}", c),
                                cmd: Some(spec),
                                tip: spec.tip_on_unknown_option,
                            });
                        }
                    }
                }
                Arity::Value => {
                    let value = if !tail.is_empty() {
                        let v = if tail.starts_with('=') { &tail[1..] } else { tail };
                        v.to_string()
                    } else {
                        match args.get(i + 1) {
                            Some(v) => {
                                i += 1;
                                v.clone()
                            }
                            None => {
                                return Err(CliError::MissingValue {
                                    display: opt.display,
                                    possible_values: opt.possible_values,
                                });
                            }
                        }
                    };
                    if tail.is_empty() && value.starts_with('-') && value != "-" {
                        return Err(CliError::MissingValue {
                            display: opt.display,
                            possible_values: opt.possible_values,
                        });
                    }
                    validate_value(opt, &value)?;
                    if parsed.values.contains_key(opt.long) {
                        return Err(CliError::DuplicateArgument {
                            display: opt.display,
                            usage: spec.usage_line.to_string(),
                        });
                    }
                    parsed.values.insert(opt.long, vec![value]);
                }
                Arity::Optional => {
                    if !tail.is_empty() {
                        let v = if tail.starts_with('=') { &tail[1..] } else { tail };
                        let value = v.to_string();
                        validate_value(opt, &value)?;
                        parsed
                            .values
                            .entry(opt.long)
                            .or_insert_with(Vec::new)
                            .push(value);
                    } else {
                        parsed
                            .values
                            .entry(opt.long)
                            .or_insert_with(Vec::new)
                            .push(String::new());
                    }
                }
                Arity::Multi => {
                    let value = if !tail.is_empty() {
                        let v = if tail.starts_with('=') { &tail[1..] } else { tail };
                        v.to_string()
                    } else {
                        match args.get(i + 1) {
                            Some(v) => {
                                i += 1;
                                v.clone()
                            }
                            None => {
                                return Err(CliError::MissingValue {
                                    display: opt.display,
                                    possible_values: opt.possible_values,
                                });
                            }
                        }
                    };
                    validate_value(opt, &value)?;
                    parsed
                        .values
                        .entry(opt.long)
                        .or_insert_with(Vec::new)
                        .push(value);
                }
            }
            i += 1;
            continue;
        }

        // Positional argument.
        if spec.accepts_positional {
            if let Some(max) = spec.max_positional {
                if parsed.positional.len() >= max {
                    return Err(CliError::UnexpectedArgument {
                        arg: arg.clone(),
                        cmd: Some(spec),
                        tip: spec.tip_on_unknown_option,
                    });
                }
            }
            parsed.positional.push(arg.clone());
        } else {
            return Err(CliError::UnexpectedArgument {
                arg: arg.clone(),
                cmd: Some(spec),
                tip: spec.tip_on_unknown_option,
            });
        }
        i += 1;
    }

    // Check for required positionals & options
    commands::validate_required(spec, &parsed)?;

    Ok(parsed)
}
